// Generic LLM Gateway contract (FR3): every path returns either
// { success: true, data: <parsed structured object> } or
// { success: false, error: <short message> } -- never an unhandled throw.
try {
  const response = $json || {};

  // A network-level failure (DNS, timeout, connection refused) surfaces here
  // as an n8n error object rather than a normal HTTP response, since the
  // HTTP Request node uses onError=continueRegularOutput.
  if (response.error) {
    const message =
      (typeof response.error === 'string' && response.error) ||
      (response.error && response.error.message) ||
      'Request to Gemini failed';
    return { json: { success: false, error: String(message) } };
  }

  const statusCode = response.statusCode;
  const body = response.body;

  if (!statusCode || statusCode < 200 || statusCode >= 300) {
    const apiMessage =
      body && body.error && body.error.message
        ? body.error.message
        : `Gemini API returned HTTP ${statusCode}`;
    return { json: { success: false, error: String(apiMessage) } };
  }

  const candidates = (body && body.candidates) || [];
  const parts =
    (candidates[0] && candidates[0].content && candidates[0].content.parts) || [];
  const text = parts[0] && parts[0].text;

  if (!text) {
    return {
      json: { success: false, error: 'Gemini response contained no text to parse' },
    };
  }

  let data;
  try {
    data = JSON.parse(text);
  } catch (parseErr) {
    return { json: { success: false, error: 'Gemini response was not valid JSON' } };
  }

  return { json: { success: true, data } };
} catch (err) {
  return { json: { success: false, error: (err && err.message) || 'Unknown LLM Gateway error' } };
}
